/* From Uiverse.io by eslam-hany - Tags: input */
.__UIV_SCOPE__ .input-container {
  position: relative;
}

.__UIV_SCOPE__ .input {
  padding: 10px;
  height: 40px;
  border: 2px solid #0B2447;
  border-top: none;
  border-bottom: none;
  font-size: 16px;
  background: transparent;
  outline: none;
  box-shadow: 7px 7px 0px 0px #0B2447;
  transition: all 0.5s;
}

.__UIV_SCOPE__ .input:focus {
  box-shadow: none;
  transition: all 0.5s;
}

.__UIV_SCOPE__ .label {
  position: absolute;
  top: 10px;
  left: 10px;
  color: #0B2447;
  transition: all 0.5s;
  transform: scale(0);
  z-index: -1;
}

.__UIV_SCOPE__ .input-container .topline {
  position: absolute;
  content: "";
  background-color: #0B2447;
  width: 0%;
  height: 2px;
  right: 0;
  top: 0;
  transition: all 0.5s;
}

.__UIV_SCOPE__ .input-container input[type="text"]:focus ~ .topline {
  width: 35%;
  transition: all 0.5s;
}

.__UIV_SCOPE__ .input-container .underline {
  position: absolute;
  content: "";
  background-color: #0B2447;
  width: 0%;
  height: 2px;
  right: 0;
  bottom: 0;
  transition: all 0.5s;
}

.__UIV_SCOPE__ .input-container input[type="text"]:focus ~ .underline {
  width: 100%;
  transition: all 0.5s;
}

.__UIV_SCOPE__ .input-container input[type="text"]:focus ~ .label {
  top: -10px;
  transform: scale(1);
  transition: all 0.5s;
}
